local({
  wd <- (haven::zap_labels(TECH2_a_hrs) + haven::zap_labels(TECH2_a_mins) / 60)
  we <- (haven::zap_labels(TECH3_a_hrs) + haven::zap_labels(TECH3_a_mins) / 60)
  (5 * wd + 2 * we) / 7
})

