local({
  thirds <- abs(Academic * 4 - round(Academic * 4)) > 1e-6
  case_when(
    thirds ~ NA_character_,
    Academic > 3.5 ~ "Good",
    Academic > 2.5 ~ "Average",
    Academic >= 1 ~ "Below average",
    .default = NA_character_
  )
})
